 private FrameLayout container;private BottomNavigationView nav;private TextInputEditText input;private TextInputLayout inputLayout;private TextView searchHelp;private String searchType="email";private ArrayList<BreachInfo> matches=new ArrayList<>();private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private static final String XON="https://api.xposedornot.com/v1/check-email/",XON_ANALYTICS="https://api.xposedornot.com/v1/breach-analytics?email=",GH="https://api.github.com/",GL="https://gitlab.com/api/v4/",BROKERS="https://raw.githubusercontent.com/Persprotect/data-broker-opt-out-list/main/data-brokers.json",PREFS="deleteme_prefs",NETWORK_NOTICE_SHOWN="network_notice_shown";
