 static class BreachInfo{String name="",domain="",date="",data="",description="",records="";boolean kept=false;}
 @Override protected void onCreate(Bundle state){super.onCreate(state);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView()).setAppearanceLightStatusBars(true);WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView()).setAppearanceLightNavigationBars(true);setContentView(R.layout.activity_main);View root=findViewById(R.id.rootLayout);ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(v.getPaddingLeft(),bars.top,v.getPaddingRight(),bars.bottom);return insets;});ViewCompat.requestApplyInsets(root);MaterialToolbar bar=findViewById(R.id.topAppBar);bar.setTitle("DeleteMe");container=findViewById(R.id.screenContainer);nav=findViewById(R.id.bottomNavigation);nav.setOnItemSelectedListener(item->{if(item.getItemId()==R.id.nav_scan){showScan();return true;}if(item.getItemId()==R.id.nav_results){showResults();return true;}if(item.getItemId()==R.id.nav_settings){showSettings();return true;}return false;});nav.setSelectedItemId(R.id.nav_scan);showNetworkNoticeOnce();}
 private void showNetworkNoticeOnce(){SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);if(p.getBoolean(NETWORK_NOTICE_SHOWN,false))return;new MaterialAlertDialogBuilder(this).setTitle("Network access").setMessage("DeleteMe needs Internet access to check breach intelligence and load official removal routes. It also reads network and Wi-Fi state to determine connectivity.").setNegativeButton("Not now",(d,w)->p.edit().putBoolean(NETWORK_NOTICE_SHOWN,true).apply()).setPositiveButton("Continue",(d,w)->p.edit().putBoolean(NETWORK_NOTICE_SHOWN,true).apply()).setOnDismissListener(d->p.edit().putBoolean(NETWORK_NOTICE_SHOWN,true).apply()).show();}
 private void showScan(){View v=getLayoutInflater().inflate(R.layout.screen_scan,container,false);container.removeAllViews();container.addView(v);input=v.findViewById(R.id.identifierInput);inputLayout=v.findViewById(R.id.identifierLayout);searchHelp=v.findViewById(R.id.searchHelp);Chip email=v.findViewById(R.id.typeEmail),mobile=v.findViewById(R.id.typeMobile),username=v.findViewById(R.id.typeUsername),name=v.findViewById(R.id.typeName);email.setOnClickListener(x->selectType("email"));mobile.setOnClickListener(x->selectType("mobile"));username.setOnClickListener(x->selectType("username"));name.setOnClickListener(x->selectType("name"));MaterialButton find=v.findViewById(R.id.findButton);find.setOnClickListener(x->scan(find));}
 private void selectType(String type){searchType=type;input.setText("");inputLayout.setError(null);if(type.equals("email")){inputLayout.setHint("Email address");input.setInputType(33);searchHelp.setText("Free breach intelligence via XposedOrNot. No API key required.");}else if(type.equals("mobile")){inputLayout.setHint("Mobile number");input.setInputType(3);searchHelp.setText("Checks public removal sources. A phone match is not claimed without a source-confirmed result.");}else if(type.equals("username")){inputLayout.setHint("Username / handle");input.setInputType(1);searchHelp.setText("Checks public GitHub and GitLab profiles without requiring an API key.");}else{inputLayout.setHint("Full name");input.setInputType(1);searchHelp.setText("Checks public developer-profile directories. Name results are potential matches, not identity proof.");}}
 private void scan(MaterialButton button){String value=input.getText()==null?"":input.getText().toString().trim();if(value.isEmpty()){inputLayout.setError("Enter something to search");return;}if(searchType.equals("email")&&!android.util.Patterns.EMAIL_ADDRESS.matcher(value).matches()){inputLayout.setError("Enter a valid email address");return;}if(searchType.equals("mobile")&&value.replaceAll("\\D","").length()<8){inputLayout.setError("Enter a valid mobile number");return;}if((searchType.equals("username")||searchType.equals("name"))&&value.length()<2){inputLayout.setError("Enter at least 2 characters");return;}inputLayout.setError(null);button.setEnabled(false);button.setText("Searching…");executor.execute(()->{try{if(searchType.equals("email"))matches=breachScan(value);else matches=genericScan(value,searchType);runOnUiThread(()->{button.setEnabled(true);button.setText("Find my data  →");showResults();});}catch(Exception e){runOnUiThread(()->{button.setEnabled(true);button.setText("Try again");Toast.makeText(this,"Could not complete the search.",Toast.LENGTH_LONG).show();});}});}
 private ArrayList<BreachInfo> genericScan(String value,String type)throws Exception{ArrayList<BreachInfo> out=new ArrayList<>();if(type.equals("username")){if(code(GH+"users/"+URLEncoder.encode(value,"UTF-8"))==200){BreachInfo b=new BreachInfo();b.name="GitHub: @"+value;b.domain="github.com";b.data="Public profile";out.add(b);}return out;}if(type.equals("name")){JSONObject o=new JSONObject(get(GH+"search/users?q="+URLEncoder.encode(value,"UTF-8")+"&per_page=10"));JSONArray a=o.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);if(u!=null){BreachInfo b=new BreachInfo();b.name="GitHub profile: @"+u.optString("login");b.domain="github.com";b.data="Public profile";out.add(b);}}return out;}BreachInfo b=new BreachInfo();b.name="Mobile removal routes available";b.data="Public directory/profile exposure may be removable";out.add(b);return out;}
 private int code(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");return c.getResponseCode();}
 private void showResults(){View v=getLayoutInflater().inflate(R.layout.screen_results,container,false);container.removeAllViews();container.addView(v);TextView title=v.findViewById(R.id.resultsTitle),sub=v.findViewById(R.id.resultsSubtitle),stat=v.findViewById(R.id.breachStat);MaterialCardView empty=v.findViewById(R.id.emptyCard);LinearLayout list=v.findViewById(R.id.resultsContent);MaterialButton directory=v.findViewById(R.id.directoryButton);stat.setText(String.valueOf(matches.size()));directory.setOnClickListener(x->showDirectory());if(matches.isEmpty()){title.setText("No confirmed matches");sub.setText("No result was returned by the checked public source.");empty.setVisibility(View.VISIBLE);}else{title.setText(matches.size()+" result"+(matches.size()==1?"":"s")+" found");sub.setText("Review where the exposure happened and exactly what data was reported before deciding what you want removed.");empty.setVisibility(View.GONE);for(BreachInfo b:matches)addBreachCard(list,b);}}
 private void addBreachCard(LinearLayout parent,BreachInfo b){MaterialCardView card=new MaterialCardView(this);card.setRadius(20);card.setCardElevation(0);card.setStrokeWidth(1);card.setStrokeColor(getColor(R.color.danger));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(18,16,18,16);TextView tag=new TextView(this);tag.setText("EXPOSURE FOUND");tag.setTextSize(11);tag.setTextColor(Color.WHITE);tag.setTypeface(null,1);tag.setPadding(10,5,10,5);tag.setBackgroundColor(getColor(R.color.danger));box.addView(tag,new LinearLayout.LayoutParams(-2,-2));box.addView(labelValue("Where was it leaked?",b.name+(b.domain.isEmpty()?"":"\n"+b.domain)));if(!b.date.isEmpty())box.addView(labelValue("Breach date",formatDate(b.date)));if(!b.records.isEmpty())box.addView(labelValue("Records exposed",b.records));if(!b.data.isEmpty())box.addView(labelValue("What data was exposed",b.data));if(!b.description.isEmpty()){TextView d=labelValue("What happened",stripHtml(b.description));d.setMaxLines(5);box.addView(d);}TextView decision=new TextView(this);decision.setText("Choose what you want to do. Keeping this result does not remove anything; review removal when you want to act.");decision.setTextSize(12);decision.setTextColor(getColor(R.color.text_secondary));decision.setPadding(0,12,0,5);box.addView(decision);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);MaterialButton keep=new MaterialButton(this);keep.setText("Keep");keep.setAllCaps(false);keep.setOnClickListener(v->{b.kept=true;keep.setText("✓ Kept");keep.setEnabled(false);});MaterialButton remove=new MaterialButton(this);remove.setText("Review removal");remove.setAllCaps(false);remove.setOnClickListener(v->showDirectory());actions.addView(keep,new LinearLayout.LayoutParams(0,50,1));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,50,1);rp.leftMargin=8;actions.addView(remove,rp);box.addView(actions);card.addView(box);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=12;parent.addView(card,p);}
 private TextView labelValue(String label,String value){TextView t=new TextView(this);t.setText(label+"\n"+value);t.setTextSize(14);t.setTextColor(getColor(R.color.text_primary));t.setLineSpacing(2,1);t.setPadding(0,11,0,0);return t;}
 private String formatDate(String s){return s.length()>=10?s.substring(0,10):s;}private String stripHtml(String s){return s.replaceAll("<[^>]*>"," ").replaceAll("&nbsp;"," ").replaceAll("&amp;","&").replaceAll("\\s+"," ").trim();}
 private ArrayList<BreachInfo> breachScan(String email)throws Exception{ArrayList<BreachInfo> out=new ArrayList<>();try{String body=get(XON_ANALYTICS+URLEncoder.encode(email,"UTF-8"));JSONObject root=new JSONObject(body);JSONArray a=root.optJSONArray("ExposedBreaches");if(a==null)a=root.optJSONArray("exposedBreaches");if(a!=null)for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;BreachInfo b=new BreachInfo();b.name=first(o,"breachID","breach_id","name","title");b.domain=first(o,"domain","breachedDomain");b.date=first(o,"breachedDate","breached_date","BreachDate");Object data=o.opt("exposedData");if(data==null)data=o.opt("xposed_data");b.data=data instanceof JSONArray?join((JSONArray)data):String.valueOf(data==null?"":data);b.description=first(o,"xposure_desc","description","Description");Object rec=o.opt("exposedRecords");if(rec==null)rec=o.opt("xposed_records");if(rec!=null&&!"null".equals(String.valueOf(rec)))b.records=String.valueOf(rec);if(!b.name.isEmpty())out.add(b);}}catch(Exception ignored){}if(out.isEmpty()){String body=get(XON+URLEncoder.encode(email,"UTF-8")+"?details=true");JSONObject o=new JSONObject(body);JSONArray a=o.optJSONArray("breaches");if(a==null)a=o.optJSONArray("data");if(a!=null)for(int i=0;i<a.length();i++){Object x=a.get(i);BreachInfo b=new BreachInfo();b.name=x instanceof JSONObject?((JSONObject)x).optString("name",((JSONObject)x).optString("title","Breach")):String.valueOf(x);if(!b.name.isEmpty())out.add(b);}}return out;}
 private static String join(JSONArray a){StringBuilder s=new StringBuilder();for(int i=0;i<a.length();i++){if(i>0)s.append(", ");s.append(a.optString(i));}return s.toString();}
 private void showDirectory(){ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,20,20,28);scroll.addView(root);addSectionHeader(root,"🇮🇳  INDIA SOURCES","Official routes for Indian services, directories and registered broker information.");for(String[] s:INDIA_SOURCES)addIndiaCard(root,s[0],s[1],s[2],s[3]);addSectionHeader(root,"GLOBAL BROKER REGISTRY","Additional international opt-out routes. A listing does not mean your record was found there.");container.removeAllViews();container.addView(scroll);executor.execute(()->{try{JSONArray a=brokerArray();runOnUiThread(()->{for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String n=first(o,"company","name","broker"),u=first(o,"optOutUrl","opt_out_url","optout_url","opt_out","url");if(n.isEmpty()||u.isEmpty())continue;addBroker(root,n,u);}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Global directory unavailable. India sources remain available.",Toast.LENGTH_LONG).show());}});}
 private void addSectionHeader(LinearLayout root,String title,String detail){TextView h=new TextView(this);h.setText(title);h.setTextSize(13);h.setTextColor(getColor(R.color.primary));h.setTypeface(null,1);h.setPadding(0,14,0,3);root.addView(h);TextView d=new TextView(this);d.setText(detail);d.setTextSize(12);d.setTextColor(getColor(R.color.text_secondary));d.setPadding(0,0,0,8);root.addView(d);}
 private void addIndiaCard(LinearLayout root,String name,String category,String url,String note){MaterialCardView c=new MaterialCardView(this);c.setRadius(18);c.setCardElevation(0);c.setStrokeWidth(1);c.setStrokeColor(getColor(R.color.india));c.setCardBackgroundColor(getColor(R.color.india_container));LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(17,15,17,15);TextView n=new TextView(this);n.setText(name);n.setTextSize(17);n.setTextColor(getColor(R.color.text_primary));n.setTypeface(null,1);b.addView(n);TextView cat=new TextView(this);cat.setText(category);cat.setTextSize(12);cat.setTextColor(getColor(R.color.india));cat.setPadding(0,3,0,3);b.addView(cat);TextView info=new TextView(this);info.setText(note);info.setTextSize(13);info.setTextColor(getColor(R.color.text_secondary));info.setPadding(0,0,0,7);b.addView(info);MaterialButton x=new MaterialButton(this);x.setText("Open official route  →");x.setAllCaps(false);x.setOnClickListener(v->open(url));b.addView(x);c.addView(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;root.addView(c,p);}
 private void addBroker(LinearLayout root,String name,String url){MaterialCardView c=new MaterialCardView(this);c.setRadius(18);c.setCardElevation(0);c.setStrokeWidth(1);c.setStrokeColor(getColor(R.color.outline));LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(17,15,17,15);TextView n=new TextView(this);n.setText(name);n.setTextSize(16);n.setTextColor(getColor(R.color.text_primary));n.setTypeface(null,1);b.addView(n);MaterialButton x=new MaterialButton(this);x.setText("Open official removal option");x.setAllCaps(false);x.setOnClickListener(v->open(url));b.addView(x);c.addView(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;root.addView(c,p);}
 private void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception ignored){Toast.makeText(this,"No app can open this route.",Toast.LENGTH_SHORT).show();}}
 private void showSettings(){View v=getLayoutInflater().inflate(R.layout.screen_settings,container,false);container.removeAllViews();container.addView(v);}
 private JSONArray brokerArray()throws Exception{Object r=new JSONTokener(get(BROKERS)).nextValue();if(r instanceof JSONArray)return(JSONArray)r;if(r instanceof JSONObject){JSONObject o=(JSONObject)r;JSONArray a=o.optJSONArray("data");if(a!=null)return a;return o.optJSONArray("brokers");}return new JSONArray();}
 private static String first(JSONObject o,String...keys){for(String k:keys){String v=o.optString(k,"");if(!v.trim().isEmpty())return v.trim();}return "";}
 private static String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","DeleteMe-OpenSource/2.0");int z=c.getResponseCode();if(z<200||z>=300)throw new IOException("HTTP "+z);InputStream i=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1)o.write(b,0,n);i.close();return o.toString(StandardCharsets.UTF_8.name());}
